void mainImage(out vec4 O, vec2 u) {

    vec2 R = iResolution.xy,
             U = (2. * u - R) / R.y * 1.3,
         C = vec2(0.0);

    float T = iTime,
          t, a = T * 0.72, I = 0.0, g, i,
          zDepth = -1000.0;

    for (; i < 1.; i += 1./22.) {
        t = fract(i + (sin(t) + 1.)*10.12 );
        vec3 P = vec3(
            sin(t * 1.9) * cos(t * 2.),
            sin(t / .034) * -sin(t * .3)*8.,
            cos(t * 20.)*(1.20)
        );
        P.xz *= mat2(cos(a), sin(a), -sin(a), cos(a));
        vec2 S = P.xy / (P.z + 1.7);

        float depth = clamp((P.z + 1.7) / 5.0, 0.0, 1.0); 

        zDepth = min(zDepth, P.z);

        g = exp(-length(U - S) * 4.7);
        I += g * (0.9 + abs(sin(T / 1e2)));
        C += g * vec2(
            i / 6.8 * (sin(i * 3.14) + 0.5),
            (0.45 + i / .12)
        ) * (.645 - depth);
    }

    float I1 = I < .94 ? 0.4 : (1.9 - I * I ) / (0.6 - I);
    vec3 finalColor = I < 0.4 ? vec3(0.4) : vec3(C.y + C.x) / (I1 * I1) * 2.0;

    O = vec4(1.0 - finalColor, 	 I < 0.6 ? -0.4 : I < 0.2 ? 0. :1.1-sqrt(I1/3.));
    if ((iFrame/300)%2==1) {
    O = vec4(pow(1.-O.r,8.));
    }
}
